from marshmallow import Schema, fields, ValidationError
import os

class UserSchema(Schema):
    username = fields.Str(required=True)
    password = fields.Str(required=True)

class AccountManager:
    def __init__(self):
        self.locked_accounts = {}
        self.failed_attempts = {}

    def login(self, username, password):
        if username in self.locked_accounts:
            raise Exception("Account is locked.")

        if not self.authenticate(username, password):
            self.failed_attempts[username] = self.failed_attempts.get(username, 0) + 1
            if self.failed_attempts[username] >= 5:
                self.locked_accounts[username] = True
            raise ValidationError("Invalid credentials.")
        else:
            self.failed_attempts[username] = 0
            return "Login successful."

    def authenticate(self, username, password):

        stored_username = os.getenv("APP_USERNAME")
        stored_password = os.getenv("APP_PASSWORD")

        return username == stored_username and password == stored_password

user_schema = UserSchema()
account_manager = AccountManager()

try:
    data = user_schema.load({"username": "user", "password": "wrongpass"})
    print(account_manager.login(data['username'], data['password']))
except ValidationError as err:
    print(err)

