from dagster import job, op
from datetime import datetime, timedelta

users = {
    "alice": {"password": "alice123", "last_changed": datetime.now()},
    "bob": {"password": "bob123", "last_changed": datetime.now()},
}

PASSWORD_EXPIRY_DAYS = 90

@op
def authenticate_user(context, username, password):
    if username in users:
        user = users[username]
        if user["password"] == password:
            if datetime.now() - user["last_changed"] > timedelta(days=PASSWORD_EXPIRY_DAYS):
                context.log.info(f"Password expired for user {username}. Please change your password.")
                return False
            context.log.info(f"User {username} authenticated successfully.")
            return True
    context.log.info(f"Authentication failed for user {username}.")
    return False

@job
def user_authentication_job():
    authenticate_user()

