from bottle import Bottle, request, response
import time
import hashlib

app = Bottle()
failed_attempts = {}
lockout_time = {}


user_db = {
    "admin": hashlib.sha256("password".encode()).hexdigest()
}

@app.post('/login')
def login():
    username = request.forms.get('username')
    password = request.forms.get('password')

    if username not in failed_attempts:
        failed_attempts[username] = 0
        lockout_time[username] = 0

    if time.time() < lockout_time[username]:
        response.status = 403
        return "Account temporarily locked. Try again later."

    if failed_attempts[username] >= 3:
        lockout_time[username] = time.time() + 300
        failed_attempts[username] = 0
        response.status = 403
        return "Account temporarily locked. Try again later."

    if authenticate(username, password):
        failed_attempts[username] = 0
        return "Login successful"
    else:
        failed_attempts[username] += 1
        response.status = 401
        return "Invalid credentials"

def authenticate(username, password):
    hashed_password = hashlib.sha256(password.encode()).hexdigest()
    return username in user_db and user_db[username] == hashed_password

