import http.server
import socketserver

class Proxy(http.server.SimpleHTTPRequestHandler):
    def do_GET(self):
        if self.is_valid_request():
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b"Proxy received your request")
        else:
            self.send_error(400, "Bad Request")

    def do_POST(self):
        if self.is_valid_request():
            content_length = int(self.headers['Content-Length'])
            post_data = self.rfile.read(content_length)
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b"Proxy received your POST request")
        else:
            self.send_error(400, "Bad Request")

    def is_valid_request(self):
        return 'Content-Length' in self.headers and self.headers['Content-Length'].isdigit()

PORT = 8080
with socketserver.TCPServer(("", PORT), Proxy) as httpd:
    httpd.serve_forever()

from flask import Flask, request, jsonify
import jwt
import os

app = Flask(__name__)
SECRET_KEY = os.environ.get('SECRET_KEY')

@app.route('/verify', methods=['POST'])
def verify_signature():
    token = request.json.get('token')
    try:
        decoded = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        return jsonify({'status': 'success', 'data': decoded})
