    consul = Consul()
    index, data = consul.kv.get(consul_key)
    if data is None:
        return None
    file_path = data['Value'].decode('utf-8')
    with open(file_path, 'r') as file:
        return file.read()

def main():
    consul_key = 'config.file'
    content = read_file_from_consul(consul_key)
    if content:
        print(content)

if __name__ == "__main__":
    main()

