    def get_kv(self, key):
        response = requests.get(self.url + 'kv/' + key, timeout=self.timeout)
        if response.status_code == 200:
            return response.json()
        return None

    def set_kv(self, key, value):
        response = requests.put(self.url + 'kv/' + key, data=value, timeout=self.timeout)
        return response.status_code == 200

    def xmlrpc_call(self, method, *params):
        server = xmlrpclib.ServerProxy(self.url + 'xmlrpc')
        return getattr(server, method)(*params)

