import luigi
from jinja2 import Environment, select_autoescape

class RenderTemplateTask(luigi.Task):
    user_input = luigi.Parameter()

    def output(self):
        return luigi.LocalTarget('output.html')

    def run(self):
        env = Environment(autoescape=select_autoescape(['html', 'xml']))
        template_string = "<html><body>{{ user_input }}</body></html>"
        template = env.from_string(template_string)
        rendered_content = template.render(user_input=self.user_input)
        with self.output().open('w') as f:
            f.write(rendered_content)

