import ctypes

app = FastAPI()

class Resource:
    def __init__(self):
        self.data = ctypes.py_object()
        self.ref_count = 0

    def acquire(self):
        if self.ref_count == 0:
            self.data = ctypes.py_object()
            ctypes.pythonapi.Py_IncRef(ctypes.py_object.from_address(id(self.data)))
        self.ref_count += 1

    def release(self):
        if self.ref_count > 0:
            self.ref_count -= 1
            if self.ref_count == 0:
                ctypes.pythonapi.Py_DecRef(ctypes.py_object.from_address(id(self.data)))

resource = Resource()

@app.get("/")
def read_root():
    resource.acquire()
    return {"Hello": "World"}

@app.get("/release")
def release_resource():
    resource.release()
    return {"Resource": "Released"}

